function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  for var i := 0 to numbers.Length - 1 do
    for var j := i + 1 to numbers.Length - 1 do
      if Abs(numbers[i] - numbers[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<char>;
  var resultList := new List<string>;
  var currentGroup := new StringBuilder;
  var ignoreSpaces := False;

  foreach var char in parenString do
  begin
    if char = ' ' then
    begin
      ignoreSpaces := True;
      continue;
    end;

    if ignoreSpaces then
    begin
      ignoreSpaces := False;
      continue;
    end;

    if char = '(' then
      stack.Push(char)
    else if char = ')' then
    begin
      if stack.Count = 0 then
        raise new System.ArgumentException('Mismatched parentheses');

      currentGroup.Append(char);
      if stack.Count = 1 then
      begin
        resultList.Add(currentGroup.ToString);
        currentGroup.Clear;
      end;
      stack.Pop;
    end;
  end;

  if stack.Count <> 0 then
    raise new System.ArgumentException('Mismatched parentheses');

  Result := resultList.ToArray;
end;


