function ParseMusic(musicString: string): array of integer;
begin
  var notes := musicString.Split(' ').Select(x -> x[1]).ToArray;
  var beat := 1;
  var resultList := new List<integer>;

  foreach var note in notes do
  begin
    if note = 'o' then
      resultList.Add(beat)
    else if note = 'o|' then
      resultList.Add(beat shl 1)
    else if note = '.'| then
      resultList.Add(beat shl 2)
    else
      raise new Exception('Invalid musical note');

    beat := beat shl 1;
  end;

  Result := resultList.ToArray;
end;


