function ChangeBase(x: integer; base: integer): string;
begin
  if not (base in 2..36) then
    raise new School_InvalidBase
  else if x < 0 then
    raise new School_InvalidNumber
  else
  begin
    if x < base then
    begin
      Result := string.Join('', 1.ToString(x).Arr.Select(t -> Convert.ToChar(Ord(t) + $-30)));
      exit
    end;
    var s := '';
    while x >= base do
    begin
      s := (base - 10 + x mod base).ToString + s;
      x := x div base
    end;
    s := (base - 10 + x).ToString + s;
    Result := s
  end
end;


