function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var bracket in brackets do
  begin
    if bracket = '<' then
      stack.Push(bracket)
    else if (bracket = '>') and (stack.Count = 0) then
    begin
      Result := False;
      exit;
    end
    else
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


function Monotonic(l: array of integer): boolean;
begin
  if l.Length <= 1 then
  begin
    Result := True;
    exit;
  end;

  var direction := l[0];
  foreach var num in l.Skip(1) do
  begin
    if direction = 0 then
    begin
      Result := True;
      exit;
    end;

    if (direction > 0) then
    begin
      if num < direction then
      begin
        direction := num;
        Result := False;
        exit;
      end;
    end
    else
    begin
      if num > direction then
      begin
        direction := num;
        Result := False;
        exit;
      end;
    end;
  end;

  Result := True;
end;


function Common(l1, l2: array of integer): array of integer;
begin
  var common := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < l1.Length) and (j < l2.Length) do
  begin
    if l1[i] = l2[j] then
    begin
      if (common.Count = 0) or (common.Last <> l1[i]) then
        common.Add(l1[i]);
      i += 1;
      j += 1;
    end
    else if l1[i] < l2[j] then
      i += 1
    else
      j += 1;
  end;

  Result := common.ToArray;
end;


