function CircularShift(x: integer; shift: integer): string;
begin
  var digits := x.ToString.ToCharArray.ToList;
  shift := shift mod digits.Count;
  if shift > 0 then
    digits.ReverseRange(0, shift);
  if shift < 0 then
    digits.Skip(digits.Count + shift);
  Result := string.Join('', digits);
end;


