  Result := num - (apples + oranges);
end;


function Pluck(arr: array of integer): array of integer;
begin
  var evenList := new List<integer>;
  var evenMin := integer.MaxValue;
  var evenIndex := -1;

  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i] < evenMin) then
    begin
      evenList.Clear;
      evenList.Add(arr[i]);
      evenMin := arr[i];
      evenIndex := i;
    end
    else if (arr[i] = evenMin) then
      evenList.Add(arr[i]);
  end;

  if evenList.Count = 1 then
    Result := [evenList[0], evenIndex]
  else
    Result := new integer[2];
end;


function Search(lst: array of integer): integer;
begin
  var count := new Dictionary<integer, integer>;
  foreach var num in lst do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  var res := -1;
  foreach var num in count.Keys do
    if num < res then
      res := num;

  while res > 0 do
  begin
    var cnt := 0;
    foreach var num in lst do
      if num >= res then
        cnt += 1;

    if cnt < res then
      break;

    res -= 1;
  end;

  Result := res;
end;


function StrangeSortList(lst: array of integer): array of integer;
begin
  if lst.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var sortedLst := lst.ToList;
  sortedLst.Sort;

  var resultList := new List<integer>;
  while sortedLst.Count > 0 do
  begin
    resultList.Add(sortedLst[0]);
    sortedLst.RemoveAt(0);

    if sortedLst.Count > 0 then
    begin
      resultList.Add(sortedLst[sortedLst.Count - 1]);
      sortedLst.RemoveAt(sortedLst.Count - 1);
    end;
  end;

  Result := resultList.ToArray;
end;


function TriangleArea(a, b, c: real): real;
begin
  if (a + b > c) and (a + c > b) and (b + c > a) then
  begin
    Result := Sqrt(4 * a * a - (b - c) * (b - c) - (a - c) * (a - c) + 
                  (b - a) * (b - a) + 2 * (a - b) * (a - b) - 
                  (b * b + c * c) * (b * b + c * c) - 
                  (a * a + c * c) * (a * a + c * c) - 
                  (a * a + b * b) * (a * a + b * b)) / 4;
    Result := Round(Result * 100) / 100;
  end
  else
    Result := -1;
end;


