function IsSimplePower(x, n: integer): boolean;
begin
  if x = 1 then
  begin
    Result := true;
    exit;
  end;

  if n = 1 then
  begin
    Result := true;
    exit;
  end;

  if (x < 2) or (n < 2) then
  begin
    Result := false;
    exit;
  end;

  var i := 2;
  while i * i <= x do
  begin
    if x mod i <> 0 then
    begin
      i += 1;
      continue;
    end;

    var base := i;
    var power := 1;
    while n > 1 do
    begin
      power *= base;
      n -= 1;
    end;

    if power = x then
    begin
      Result := true;
      exit;
    end;

    i += 1;
  end;

  Result := false;
end;


