function Encrypt(s: string): string;
begin
  var encrypted := '';
  foreach var ch in s do
  begin
    if ch.IsLetter then
    begin
      var shift := 2;
      if ch.IsUpper then
        shift := 1;

      if ch.IsLower then
        shift := shift * 2;

      var newChar := Chr((Ord(ch) - Ord('a') + shift) mod 26 + Ord('a'));
      if ch.IsLower then
        Result := Result + newChar
      else
        Result := Result + newChar.ToUpper;
    end
    else
      Result := Result + ch;
  end;
end;


