function Multiply(a, b: integer): integer;
begin
  var product := 0;
  var aDigit := 0;
  var bDigit := 0;
  var sign := 1;

  if (a < 0) or (b < 0) then
  begin
    sign := -1;
    a := -a;
    b := -b;
  end;

  while a > 0 do
  begin
    aDigit := a mod 10;
    a := a div 10;

    while b > 0 do
    begin
      bDigit := b mod 10;
      b := b div 10;
      product := product + aDigit * bDigit * (10 - product mod 10);
    end;
  end;

  Result := sign * product;
end;


