function ClosestInteger(value: string): integer;
begin
  var sign := 1;
  if value[1] = '-' then
    sign := -1;

  var cleaned := value.Substring(1).Replace('.', '');
  if cleaned[0] = '0' then
    cleaned := cleaned.Substring(1);

  if cleaned = '' then
    Result := 0
  else
  begin
    var closest := integer(StrToInt(cleaned[
      1
    ]));
    for var i := 2 to cleaned.Length do
      if Abs(integer(StrToInt(cleaned[i]))) < Abs(closest) then
        closest := integer(StrToInt(cleaned[i]));

    Result := sign * closest;
  end;
end;


