function EvenOddPalindrome(n: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  for var i := 1 to n do
  begin
    var numStr := i.ToString;
    var left := 0;
    var right := numStr.Length - 1;
    var isPalindrome := True;
    while left < right do
    begin
      if numStr[left] <> numStr[right] then
      begin
        isPalindrome := False;
        break;
      end;
      left += 1;
      right -= 1;
    end;
    if isPalindrome then
    begin
      if i mod 2 = 0 then
        evenCount += 1;
      else
        oddCount += 1;
    end;
  end;
  Result := (evenCount, oddCount);
end;


function CountNums(arr: array of integer): integer;
begin
  var count := 0;
  foreach var num in arr do
  begin
    if num < 0 then
    begin
      var firstDigit := -1 * (num div Abs(num));
      if firstDigit > 0 then
        count := count + 1;
    end
    else
    begin
      var sumOfDigits := 0;
      var numStr := Abs(num).ToString;
      foreach var digitChar in numStr do
        sumOfDigits := sumOfDigits + StrToInt(digitChar.ToString);
      if sumOfDigits > 0 then
        count := count + 1;
    end;
  end;
  Result := count;
end;


