end;


function Exchange(lst1, lst2: array of integer): string;
begin
  var evenCount1 := 0;
  var evenCount2 := 0;
  var oddCount1 := 0;
  var oddCount2 := 0;

  for var i := 0 to lst1.Length - 1 do
  begin
    if lst1[i] mod 2 = 0 then
      evenCount1 += 1
    else
      oddCount1 += 1;

    if lst2[i] mod 2 = 0 then
      evenCount2 += 1
    else
      oddCount2 += 1;
  end;

  if (evenCount1 + evenCount2) > (lst1.Length + lst2.Length) / 2 then
    Result := 'NO'
  else if (evenCount1 + evenCount2) < (lst1.Length + lst2.Length) / 2 then
    Result := 'YES'
  else
    Result := 'YES';
end;


