end;


function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var n := grid.Length;
  var m := grid[0].Length;
  var res := 0;
  var buckets := new integer[n, m];

  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i, j] = 1 then
      begin
        buckets[i, j] := 1;
        for var k := 0 to n - 1 do
          if (k < i) and (buckets[k, j] = 1) then
            buckets[i, j] := 2;
        for var k := 0 to m - 1 do
          if (k < j) and (buckets[i, k] = 1) then
            buckets[i, j] := 2;
      end;

  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if buckets[i, j] = 2 then
      begin
        var count := 0;
        for var k := 0 to n - 1 do
          if buckets[k, j] = 1 then
            count += 1;
        for var k := 0 to m - 1 do
          if buckets[i, k] = 1 then
            count += 1;
        res += Min(capacity, count) + 1;
        buckets[i, j] := 1;
      end;

  for var k := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if buckets[k, j] = 1 then
      begin
        buckets[k, j] := 2;
        for var i := 0 to n - 1 do
          for var l := 0 to m - 1 do
            if buckets[i, l] = 1 then
              buckets[k, j] := 2;
        res += 1;
      end;

  Result := res;
end;


