    end;

    if cnt = n then
      res.Add(temp);
  end;

  Result := res.ToArray;
end;


function GetClosestVowel(word: string): string;
begin
  var vowels := HSet('a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U');
  var lastConsonantPos := -1;
  var closestVowel := #0;

  for var i := word.Length - 1 downto 0 do
  begin
    if not vowels.Contains(word[i]) then
    begin
      if (i - lastConsonantPos > 2) and (i <> word.Length - 1) then
      begin
        closestVowel := word[i];
        Result := closestVowel;
        exit;
      end;
      lastConsonantPos := i;
    end;
  end;
  Result := closestVowel;
end;


function MatchParens(lst: array of string): string;
