      st.Push(ch)
    else if (ch = ')') and (st.Count = 0) then
    begin
      Result := 'No';
      exit;
    end
    else
      st.Pop;
  end;
  if st.Count = 0 then
    Result := 'Yes'
  else
    Result := 'No';
end;


