function GetOddCollatz(n: integer): array of integer;
begin
  var seq := new List<integer>;
  var oddSeq := new List<integer>;

  while n <> 1 do
  begin
    seq.Add(n);
    if n mod 2 <> 0 then
      oddSeq.Add(n)
    else
      n := n div 2;
  end;
  seq.Add(1);

  for var i := 0 to seq.Count - 1 do
    if seq[i] mod 2 <> 0 then
      oddSeq.Add(seq[i]);

  Result := oddSeq.ToArray;
end;


