    var dd := StrToInt(parts[1]);
    var yyyy := StrToInt(parts[2]);

    if (mm < 1) or (mm > 12) then
      Result := False
    else if (dd < 1) or (dd > 31) then
      Result := False
    else if (mm = 2) and (dd > 29) then
