function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new List<(integer, integer)>;
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      directions.Add((i, j));
  directions.Sort((a, b) ->
  begin
    var (i1, j1) := a;
    var (i2, j2) := b;
    if i1 < i2 then Result := -1
    else if i1 > i2 then Result := 1
    else if j1 < j2 then Result := -1
    else if j1 > j2 then Result := 1
    else Result := 0;
  end);
  var ans := new List<integer>;
  var visited := new HashSet<(integer, integer)>;
  var q := new Queue<(integer, integer, integer)>;
  q.Enqueue((-1, -1, 0));
  while q.Count > 0 do
  begin
    var (i, j, cnt) := q.Dequeue;
    if (i = n - 1) and (j = n - 1) then
    begin
      Result := ans.ToArray;
      exit;
    end;
    if (i >= 1) and (visited.Contains((i - 1, j))) and ((i - 1, j) <> (i, j)) then
      continue;
    if (j >= 1) and visited.Contains((i, j - 1)) and ((i, j - 1) <> (i, j)) then
      continue;
    ans.Add(grid[i, j]);
    visited.Add((i, j));
    if cnt + 1 = k then
    begin
      Result := ans.ToArray;
      exit;
    end;
    foreach var (di, dj) in directions do
    begin
      var ni := i + di;
      var nj := j + dj;
      if (ni >= 0) and (ni < n) and (nj >= 0) and (nj < n) and
         ((ni <> i) or (nj <> j)) and not visited.Contains((ni, nj)) then
      begin
        q.Enqueue((ni, nj, cnt + 1));
      end;
    end;
  end;
  Result := new integer[0];
end;


function Tri(n: integer): array of real;
begin
  var trib := new List<real>;
  trib.Add(3);
  if n > 0 then
  begin
    trib.Add(1);
    if n mod 2 = 0 then
      trib.Add(1)
    else
      trib.Add(1 + n div 2);
  end;

  for var i := 4 to n do
  begin
    if i mod 2 = 0 then
      trib.Add(trib[trib.Count - 1] + trib[trib.Count - 2] + trib[trib.Count - 3])
    else
      trib.Add(trib[trib.Count - 1] + trib[trib.Count - 2] + trib[trib.Count - 3] + 1);
  end;

  Result := trib.ToArray;
end;


function Digits(n : integer): integer;
begin
  var product := 1;
  var hasOdd := False;
  foreach var digit in n.ToString() do
  begin
    var digitValue := StrToInt(digit.ToString());
    if (digitValue mod 2 <> 0) then
    begin
      product *= digitValue;
      hasOdd := True;
    end;
  end;
  if not hasOdd then
    Result := 0
  else
    Result := product;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      var top := stack.Pop;
      if top <> '[' then
      begin
        Result := False;
        exit;
      end;
    end
    else
      stack.Push(ch);
  end;
  if stack.Count <> 0 then
  begin
    Result := False;
    exit;
  end;
  Result := True;
end;


