  for var i := n - 2 downto 0 do
  begin
    if arr[i] > arr[i + 1] then
    begin
      maxIndex := i;
      maxVal := arr[i];
      break;
    end;
  end;
  if maxIndex <> -1 then
  begin
    for var i := maxIndex + 1 to n - 1 do
    begin
      if arr[i] >= arr[maxIndex] then
      begin
        maxIndex := -1;
        break;
      end;
    end;
    if maxIndex <> -1 then
      Result := maxIndex
    else
      Result := -1;
  end
  else
    Result := -1;
end;


