function IsEqualToSumEven(n: integer): boolean;
begin
  if n mod 2 <> 0 then
    Result := False
  else
  begin
    var a := 2;
    var b := 4;
    var c := 2;
    var d := 2;
    var sum := n div 2;
    while a < sum do
    begin
      if (a + b = sum) and (c + d = sum) and (a + c = 2 * sum) and (b + d = 2 * sum) then
      begin
        Result := True;
        exit;
      end;
      a += 2;
      b += 2;
      c += 2;
      d += 2;
    end;
    Result := False;
  end;
end;


