function FixSpaces(text: string): string;
begin
  var newText := '';
  var spaces := 0;
  foreach var ch in text do
  begin
    if ch = ' ' then
    begin
      spaces += 1;
      if spaces = 1 then
        newText += ch
      else if spaces = 2 then
        newText += ch + '-'
      else
        newText += newText.Length + '_';
    end
    else
    begin
      newText += ch;
      spaces := 0;
    end;
  end;
  Result := newText;
end;


