  while numStr > 0 do
  begin
    var digit := numStr mod 10;
    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;
    numStr := numStr div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
