    num -= 1000;
  end;
  if num >= 900 then
  begin
    roman += 'cm';
    num -= 900;
  end;
  while num >= 90 do
  begin
    roman += 'c';
    num -= 90;
  end;
  while num >= 50 do
  begin
    roman += 'l';
    num -= 50;
  end;
  if num >= 40 then
  begin
    roman += 'xl';
    num -= 40;
  end;
  while num >= 10 do
  begin
    roman += 'x';
    num -= 10;
  end;
  while num >= 9 do
  begin
    roman += 'i';
    num -= 9;
  end;
  while num >= 5 do
  begin
    roman += 'v';
    num -= 5;
  end;
  if num >= 4 then
  begin
    roman += 'iv';
    num -= 4;
  end;
