function Solve(s: string): string;
begin
  var letters := new List<char>;
  var digits := new List<char>;
  var specials := new List<char>;

  foreach var ch in s do
  begin
    if ch.IsLetter then
      letters.Add(ch)
    else if ch.IsDigit then
      digits.Add(ch)
    else
      specials.Add(ch);
  end;

  var lettersList := letters.ToArray;
  var digitsList := digits.ToArray;
  var specialsList := specials.ToArray;

  var lower := new List<char>;
  var upper := new List<char>;
  var digits := new List<char>;
  var specials := new List<char>;

  var i := 0;
  while i < s.Length do
  begin
    var ch := s[i];
    if ch.IsLetter then
    begin
      if ch.IsUpper then
        upper.Add(ch)
      else
        lower.Add(ch);
    end
    else if ch.IsDigit then
      digits.Add(ch)
    else
      specials.Add(ch);
    i += 1;
  end;

  var res := '';
  for var j := 0 to s.Length - 1 do
  begin
    var ch := s[j];
    if ch.IsLetter then
    begin
      if ch.IsUpper then
        res += upper[j]
      else
        res += lower[j];
    end
    else if ch.IsDigit then
      res += digits[j]
    else
      res += specials[j];
  end;

  Result := res;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := '';
    exit;
  end;
  var h := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var m := new System.Text.StringBuilder;
  var b := new byte[16];
  var a := System.Text.Encoding.ASCII.GetBytes(text);
  h.ComputeHash(a, 0, a.Length, b, 0);
  for var i := 0 to b.Length - 1 do
    m.Append(b[i].ToString('x2'));
  Result := m.ToString;
end;


